// NPCR Book 2 lesson dialogues (lecciones 11-20)
window.B2_TEXTS = [
{l:11,t:"我玩儿得非常高兴",tes:"Me divertí mucho",ten:"I had a great time",parts:[
{ies:"Lin Na ha venido a cambiar dinero al banco, donde se encuentra con Ding Libo.",ien:"Lin Na comes to the bank to change money and runs into Ding Libo.",lines:[
{s:"林娜",zh:"力波, 你来得真早!",es:"¡Libo, llegaste muy temprano!",en:"Libo, you're here really early!"},
{s:"丁力波",zh:"我来换钱, 刚才银行人少, 不用排队。",es:"Vine a cambiar dinero; hace un rato había poca gente y no hacía falta hacer cola.",en:"I came to change money — it wasn't busy just now, no need to queue."},
{s:"林娜",zh:"今天一百英镑换多少人民币?",es:"¿A cuánto están hoy cien libras en renminbi?",en:"How much RMB do a hundred pounds get today?"},
{s:"丁力波",zh:"我查查, 一百英镑换八百七十五块六。",es:"Déjame ver… cien libras son 875,60 yuanes.",en:"Let me check — a hundred pounds is 875.60 yuan."},
{s:"林娜",zh:"我也来换钱。我明天去上海旅行, 要用人民币。",es:"Yo también vengo a cambiar. Mañana viajo a Shanghai y necesito renminbi.",en:"I'm changing money too. I'm traveling to Shanghai tomorrow and need RMB."},
{s:"丁力波",zh:"你刚从西安回北京, 又要去上海, 你真喜欢旅行! 在西安玩儿得怎么样?",es:"Acabas de volver de Xi'an y ya vas a Shanghai… ¡te encanta viajar! ¿Qué tal lo pasaste en Xi'an?",en:"You just got back from Xi'an and you're off to Shanghai — you really love traveling! How was Xi'an?"},
{s:"林娜",zh:"玩儿得非常高兴。",es:"Me divertí muchísimo.",en:"I had a wonderful time."},
{s:"丁力波",zh:"吃得好不好?",es:"¿Comiste bien?",en:"Did you eat well?"},
{s:"林娜",zh:"吃得还可以。这次住得不太好, 宾馆的房间太小了。",es:"Comí bastante bien. Esta vez el alojamiento no fue muy bueno: la habitación del hotel era muy pequeña.",en:"The food was OK. The lodging wasn't great though — the hotel room was too small."},
{s:"丁力波",zh:"你参观兵马俑博物馆了没有?",es:"¿Visitaste el museo de los Guerreros de Terracota?",en:"Did you visit the Terracotta Warriors museum?"},
{s:"林娜",zh:"参观了, 还吃了西安的小吃, 买了很多明信片, 你到我那儿去看看吧。",es:"Sí, y también probé los bocadillos de Xi'an y compré muchas postales; ven a mi cuarto a verlas.",en:"I did, and I tried Xi'an snacks and bought lots of postcards — come over and see them."},
{s:"丁力波",zh:"好啊。我也很想去西安旅行, 你给我介绍介绍吧。哦, 该你了。",es:"¡Claro! Yo también quiero viajar a Xi'an; cuéntame. Ah, te toca a ti.",en:"Sure. I'd love to visit Xi'an too — tell me about it. Oh, it's your turn."},
{s:"林娜",zh:"你好, 我想换人民币。这是五百英镑。",es:"Hola, quiero cambiar a renminbi. Aquí tiene quinientas libras.",en:"Hello, I'd like to change into RMB. Here are five hundred pounds."},
{s:"营业员",zh:"好, 请等一等……请您在这儿签个字。",es:"Bien, un momento… Firme aquí, por favor.",en:"OK, one moment… Please sign here."},
{s:"林娜",zh:"好的。",es:"De acuerdo.",en:"All right."},
{s:"营业员",zh:"给您, 这是四千三百七十八块人民币, 请数一数。",es:"Aquí tiene: 4.378 yuanes; cuéntelos, por favor.",en:"Here you are: 4,378 yuan — please count it."}]},
{ies:"Ma Dawei se encuentra con Lin Na en el campus.",ien:"Ma Dawei runs into Lin Na on campus.",lines:[
{s:"马大为",zh:"林娜, 好久不见, 你回英国了吗?",es:"Lin Na, ¡cuánto tiempo! ¿Volviste al Reino Unido?",en:"Lin Na, long time no see — did you go back to the UK?"},
{s:"林娜",zh:"没有, 我去上海了, 昨天刚回北京。",es:"No, fui a Shanghai; volví a Beijing ayer.",en:"No, I went to Shanghai — I just got back yesterday."},
{s:"马大为",zh:"你觉得上海怎么样?",es:"¿Qué te pareció Shanghai?",en:"What did you think of Shanghai?"},
{s:"林娜",zh:"上海很大, 很漂亮。",es:"Es enorme y muy bonita.",en:"It's huge and beautiful."},
{s:"马大为",zh:"听说上海发展得非常快, 是不是?",es:"Dicen que Shanghai se desarrolla rapidísimo, ¿verdad?",en:"I hear Shanghai is developing incredibly fast, right?"},
{s:"林娜",zh:"是啊。特别是浦东, 又建了不少高楼大厦, 还有世博园和迪士尼乐园。",es:"Sí, sobre todo Pudong: construyeron muchos rascacielos más, y están el Parque de la Expo y Disneylandia.",en:"Yes — especially Pudong: lots of new skyscrapers, plus the Expo Park and Disneyland."},
{s:"马大为",zh:"我也想去世博园看一看。",es:"Yo también quiero ver el Parque de la Expo.",en:"I'd like to see the Expo Park too."},
{s:"林娜",zh:"外滩也很好, 夜景特别美。",es:"El Bund también es precioso; el paisaje nocturno es bellísimo.",en:"The Bund is also great — the night view is gorgeous."},
{s:"马大为",zh:"上海的商场非常多, 东西贵不贵?",es:"Shanghai tiene muchísimos centros comerciales. ¿Es caro?",en:"Shanghai has tons of malls — is stuff expensive?"},
{s:"林娜",zh:"不太贵。上海人衣服做得真好, 我买了两件毛衣、三条裙子。",es:"No mucho. La ropa que hacen es buenísima: compré dos jerséis y tres faldas.",en:"Not too bad. They make great clothes — I bought two sweaters and three skirts."},
{s:"马大为",zh:"你买了这么多衣服! 听说上海人喜欢说上海话, 他们普通话说得怎么样?",es:"¡Cuánta ropa compraste! Dicen que allí prefieren hablar shanghainés. ¿Qué tal hablan mandarín?",en:"That's a lot of clothes! I hear they like speaking Shanghainese — how's their Mandarin?"},
{s:"林娜",zh:"他们普通话说得很好, 年轻人英语说得也很流利。",es:"Hablan muy bien mandarín, y los jóvenes hablan inglés con fluidez.",en:"Their Mandarin is very good, and young people speak fluent English."},
{s:"马大为",zh:"你学没学上海话?",es:"¿Aprendiste algo de shanghainés?",en:"Did you learn any Shanghainese?"},
{s:"林娜",zh:"学了一句, “阿拉勿懂”。",es:"Una frase: «ala vu dong».",en:"One phrase: \"ala vu dong\"."},
{s:"马大为",zh:"你说什么? 我不懂。",es:"¿Qué dijiste? No entiendo.",en:"What did you say? I don't understand."},
{s:"林娜",zh:"这就是上海话的“我不懂”。",es:"Eso es «no entiendo» en shanghainés.",en:"That's Shanghainese for \"I don't understand\"."}]}]},
{l:12,t:"您要寄到哪儿",tes:"Adónde quieres hacer el envío",ten:"Where are you sending it",parts:[
{ies:"Ma Dawei va a la oficina de correos para enviar un paquete.",ien:"Ma Dawei goes to the post office to send a parcel.",lines:[
{s:"马大为",zh:"您好, 请问哪儿可以寄包裹?",es:"Hola, ¿dónde puedo enviar un paquete?",en:"Hello, where can I mail a parcel?"},
{s:"保安",zh:"您去那边拿一张单子, 看到了吗?",es:"Vaya allí y tome un formulario, ¿lo ve?",en:"Go over there and take a form — see it?"},
{s:"马大为",zh:"看到了。",es:"Sí, lo veo.",en:"I see it."},
{s:"保安",zh:"拿了单子以后去7号窗口。",es:"Después de tomar el formulario, vaya a la ventanilla 7.",en:"After you get the form, go to window 7."},
{s:"马大为",zh:"谢谢!",es:"¡Gracias!",en:"Thanks!"},
{s:"马大为",zh:"您好, 我要寄包裹。",es:"Hola, quiero enviar un paquete.",en:"Hi, I'd like to send a parcel."},
{s:"营业员",zh:"这儿不寄包裹。请您去7号窗口。",es:"Aquí no se envían paquetes. Vaya a la ventanilla 7.",en:"We don't handle parcels here. Please go to window 7."},
{s:"马大为",zh:"是7号? 哦, 刚才我听错了。不好意思。",es:"¿La 7? Ah, escuché mal hace un momento. Disculpe.",en:"Window 7? Oh, I misheard earlier. Sorry."},
{s:"马大为",zh:"我要寄这个包裹。",es:"Quiero enviar este paquete.",en:"I'd like to send this parcel."},
{s:"营业员",zh:"您要寄到哪儿?",es:"¿Adónde lo envía?",en:"Where are you sending it?"},
{s:"马大为",zh:"美国。",es:"A Estados Unidos.",en:"To the United States."},
{s:"营业员",zh:"航空还是海运? 航空一星期, 海运两个月。",es:"¿Por avión o por barco? Por avión, una semana; por barco, dos meses.",en:"Air or sea? Air takes a week; sea takes two months."},
{s:"马大为",zh:"对不起, 我没听清楚。您说得太快了, 请再说一遍。",es:"Perdone, no le entendí bien. Habla muy rápido; ¿puede repetirlo?",en:"Sorry, I didn't catch that. You spoke too fast — could you say it again?"},
{s:"营业员",zh:"您要寄航空还是海运? 寄航空要一个星期左右, 海运一般两个月以后到。",es:"¿Lo envía por avión o por barco? Por avión tarda alrededor de una semana; por barco suele llegar en dos meses.",en:"Air or sea mail? Airmail takes about a week; sea mail usually arrives after two months."},
{s:"马大为",zh:"哦, 现在听懂了, 谢谢。请问寄航空多少钱?",es:"Ah, ahora sí entendí, gracias. ¿Cuánto cuesta por avión?",en:"Oh, now I understand, thanks. How much is airmail?"},
{s:"营业员",zh:"我要称一下, 包裹放在这儿吧。邮费是二百五十元。",es:"Tengo que pesarlo; ponga el paquete aquí. El envío cuesta 250 yuanes.",en:"I need to weigh it — put the parcel here. The postage is 250 yuan."},
{s:"马大为",zh:"这么贵! 海运呢?",es:"¡Qué caro! ¿Y por barco?",en:"That expensive! What about sea mail?"},
{s:"营业员",zh:"海运的邮费是一百一十元。",es:"Por barco son 110 yuanes.",en:"Sea mail is 110 yuan."},
{s:"马大为",zh:"我寄海运吧。",es:"Entonces lo mando por barco.",en:"I'll send it by sea then."},
{s:"营业员",zh:"好。请您填一下这张单子。这儿写您的姓名, 这儿写收件人的姓名。",es:"Bien. Rellene este formulario: aquí su nombre y aquí el del destinatario.",en:"OK. Please fill in this form: your name here, the recipient's name here."},
{s:"马大为",zh:"填完了。您看, 我写对了吗?",es:"Listo. ¿Lo escribí bien?",en:"Done. Did I write it correctly?"},
{s:"营业员",zh:"您写得很对, 汉字写得很漂亮。最后, 您还得签个字, 就签在这儿。……这是您的包裹单。",es:"Está muy bien, y sus caracteres son muy bonitos. Por último, firme aquí. … Este es su comprobante.",en:"It's all correct — your characters are lovely. Finally, sign here. … Here's your parcel receipt."}]},
{ies:"Ding Libo regresa al dormitorio a buscar a Ma Dawei.",ien:"Ding Libo comes back to the dorm to see Ma Dawei.",lines:[
{s:"丁力波",zh:"大为, 我朋友寄来一个包裹。",es:"Dawei, un amigo me mandó un paquete.",en:"Dawei, a friend mailed me a parcel."},
{s:"马大为",zh:"你专门跑来告诉我, 包裹里一定是好东西。",es:"Si viniste corriendo solo para contármelo, seguro que trae algo bueno.",en:"If you ran over just to tell me, it must be something good."},
{s:"丁力波",zh:"是新版的《新实用汉语课本》, 我要送给我爸爸。他三十年以前用的第一本汉语书是老《实用汉语课本》。",es:"Es la nueva edición del «Nuevo Libro de Chino Práctico»; se la regalaré a mi papá. Su primer libro de chino, hace treinta años, fue el viejo «Libro de Chino Práctico».",en:"It's the new edition of New Practical Chinese Reader — a gift for my dad. His first Chinese textbook thirty years ago was the old Practical Chinese Reader."},
{s:"马大为",zh:"你爸爸一定会喜欢这套新书。",es:"Seguro que a tu papá le encantará esta nueva serie.",en:"Your dad will definitely love the new set."},
{s:"丁力波",zh:"是啊。快递员下午送来, 可是我不在宿舍, 可以让他送到你这儿吗?",es:"Sí. El mensajero lo trae por la tarde, pero yo no estaré; ¿puede entregártelo a ti?",en:"Yeah. The courier delivers this afternoon but I won't be in — can he leave it with you?"},
{s:"马大为",zh:"快递员几点来?",es:"¿A qué hora viene el mensajero?",en:"What time does the courier come?"},
{s:"丁力波",zh:"不知道。他只说下午过来。",es:"No sé; solo dijo que por la tarde.",en:"No idea — he just said the afternoon."},
{s:"马大为",zh:"我看看。我五点以后要出去, 五点以前可以替你收。",es:"A ver… salgo después de las cinco; antes de las cinco puedo recibirlo por ti.",en:"Let's see — I'm going out after five, so I can take it for you before five."},
{s:"丁力波",zh:"没关系。我四点办完事就回宿舍来。",es:"No importa: termino mis cosas a las cuatro y vuelvo al dormitorio.",en:"No worries — I'll finish my errand at four and come back."},
{s:"马大为",zh:"好的, 没问题!",es:"¡Perfecto, sin problema!",en:"Great, no problem!"},
{s:"快递员",zh:"喂, 您好。请问您是丁力波吗?",es:"¿Aló? ¿Es usted Ding Libo?",en:"Hello, is this Ding Libo?"},
{s:"丁力波",zh:"是的。您是哪位?",es:"Sí. ¿Quién habla?",en:"Yes. Who's calling?"},
{s:"快递员",zh:"我是快递员。您有一个快递, 我一会儿送去。您在家吗?",es:"Soy el mensajero. Tiene un envío; se lo llevo en un rato. ¿Está en casa?",en:"I'm the courier. You have a delivery — I'll bring it shortly. Are you home?"},
{s:"丁力波",zh:"不好意思, 我现在不在。您送到四层403房间, 好吗? 我的朋友可以帮我收。",es:"Lo siento, ahora no estoy. ¿Puede llevarlo al cuarto 403 del cuarto piso? Mi amigo lo recibirá.",en:"Sorry, I'm out right now. Could you deliver it to room 403 on the 4th floor? My friend will take it."},
{s:"快递员",zh:"好的。",es:"De acuerdo.",en:"Sure."},
{s:"快递员",zh:"您好, 您的朋友不在房间。我得回公司去了, 明天再来送吧。",es:"Hola, su amigo no está en la habitación. Tengo que volver a la empresa; se lo traigo mañana.",en:"Hi — your friend isn't in the room. I have to head back; I'll deliver it tomorrow."},
{s:"丁力波",zh:"不会啊, 我们刚通了电话, 他就在宿舍。您再敲敲门。",es:"No puede ser: acabamos de hablar por teléfono y está en el dormitorio. Toque otra vez.",en:"That can't be — we just spoke and he's in the dorm. Knock again."},
{s:"快递员",zh:"您告诉我三层304房间, 是吗?",es:"Me dijo el cuarto 304 del tercer piso, ¿no?",en:"You told me room 304 on the 3rd floor, right?"},
{s:"丁力波",zh:"不是, 是四层403房间。",es:"No: cuarto piso, habitación 403.",en:"No — 4th floor, room 403."},
{s:"快递员",zh:"啊, 不好意思, 我自己记错了, 以为是三层呢。我现在就上去。",es:"Ay, disculpe, lo apunté mal; creí que era el tercero. Subo ahora mismo.",en:"Ah, my bad — I remembered it wrong and thought it was the 3rd floor. I'll go up right now."},
{s:"丁力波",zh:"没关系, 可能是我没说清楚。辛苦您了!",es:"No pasa nada; quizá no lo dije claro. ¡Gracias por la molestia!",en:"No problem — maybe I wasn't clear. Thanks for your trouble!"}]}]},
{l:13,t:"请您把姓名和手机号写在这儿",tes:"Por favor, escribe aquí tu nombre y número de móvil",ten:"Please write your name and phone number here",parts:[
{ies:"Ding Libo llega a China Móvil para comprar una tarjeta SIM.",ien:"Ding Libo goes to China Mobile to buy a SIM card.",lines:[
{s:"丁力波",zh:"您好! 我的手机丢了, 我想办一张新的手机卡。",es:"¡Hola! Perdí mi móvil y quiero sacar una tarjeta SIM nueva.",en:"Hi! I lost my phone and I'd like to get a new SIM card."},
{s:"营业员",zh:"您要换一个新的手机号吗?",es:"¿Quiere cambiar de número?",en:"Do you want a new phone number?"},
{s:"丁力波",zh:"不是。我想买一张新卡, 还用以前的手机号。",es:"No; quiero una tarjeta nueva pero conservar mi número.",en:"No — a new card, but keeping my old number."},
{s:"营业员",zh:"好的。您带身份证来了吗?",es:"Bien. ¿Trajo su carné de identidad?",en:"OK. Did you bring your ID card?"},
{s:"丁力波",zh:"不好意思, 我没有中国的身份证。",es:"Lo siento, no tengo carné de identidad chino.",en:"Sorry, I don't have a Chinese ID card."},
{s:"营业员",zh:"啊, 您是外国人, 您汉语说得真好。您带护照来了吗?",es:"Ah, es extranjero… ¡habla muy bien chino! ¿Trajo su pasaporte?",en:"Ah, you're a foreigner — your Chinese is great! Did you bring your passport?"},
{s:"丁力波",zh:"护照我也没带。我要办签证, 昨天把护照送到大使馆了。",es:"Tampoco lo traje: estoy tramitando la visa y ayer dejé el pasaporte en la embajada.",en:"I don't have it either — I'm applying for a visa and left my passport at the embassy yesterday."},
{s:"营业员",zh:"您拿到签证以后带护照来办卡吧。",es:"Cuando tenga la visa, venga con el pasaporte a hacer el trámite.",en:"Once you get your visa, come back with your passport."},
{s:"丁力波",zh:"不行啊。他们两个星期以后才把护照还给我。我不能这么长时间不用手机啊。对了, 我带学生证了, 学生证可以吗?",es:"No puedo: me devuelven el pasaporte recién en dos semanas y no puedo estar tanto tiempo sin móvil. Ah, traje mi carné de estudiante, ¿sirve?",en:"That won't work — they won't return it for two weeks, and I can't go that long without a phone. Oh, I have my student ID — will that do?"},
{s:"营业员",zh:"学生证不行。您有中国的驾照吗?",es:"El carné de estudiante no sirve. ¿Tiene licencia de conducir china?",en:"A student ID won't do. Do you have a Chinese driver's license?"},
{s:"丁力波",zh:"有。",es:"Sí.",en:"I do."},
{s:"营业员",zh:"好。请您把姓名和手机号写在这儿, 把驾照交给我, 我复印一下。",es:"Bien. Escriba aquí su nombre y su número, y déme la licencia para fotocopiarla.",en:"Great. Write your name and number here, and give me the license to photocopy."},
{s:"营业员",zh:"这是您的驾照, 这是新的手机卡。您可以把卡装在手机上, 试一试。",es:"Aquí tiene su licencia y la tarjeta nueva. Póngala en el móvil y pruébela.",en:"Here's your license and the new SIM. Put it in your phone and try it."},
{s:"丁力波",zh:"好的。……现在可以用了, 谢谢!",es:"Vale… ¡Ya funciona, gracias!",en:"OK… It works now, thanks!"},
{s:"营业员",zh:"不客气, 欢迎您再来。",es:"De nada; vuelva cuando quiera.",en:"You're welcome — come again."}]},
{ies:"Lin Na compra un billete de tren; Ding Libo la recoge en la estación.",ien:"Lin Na buys a train ticket; Ding Libo picks her up at the station.",lines:[
{s:"林娜",zh:"您好, 我要买一张去北京的火车票。请问, 还能买到明天上午的高铁票吗?",es:"Hola, quiero un billete de tren a Beijing. ¿Todavía quedan billetes de alta velocidad para mañana por la mañana?",en:"Hi, I'd like a train ticket to Beijing. Are there still high-speed tickets for tomorrow morning?"},
{s:"营业员",zh:"能。G2次怎么样? 9点开, 13点48分到北京。",es:"Sí. ¿Le va bien el G2? Sale a las 9 y llega a Beijing a las 13:48.",en:"Yes. How about the G2? It leaves at 9 and arrives in Beijing at 13:48."},
{s:"林娜",zh:"9点太早了, 有10点左右的车票吗?",es:"Las 9 es muy temprano; ¿hay algo alrededor de las 10?",en:"9 is too early — anything around 10?"},
{s:"营业员",zh:"有, G14次。10点开, 14点58分到。",es:"Sí, el G14: sale a las 10 y llega a las 14:58.",en:"Yes, the G14: departs at 10, arrives 14:58."},
{s:"林娜",zh:"好, 我要这趟。",es:"Perfecto, me quedo con ese.",en:"Great, I'll take that one."},
{s:"丁力波",zh:"林娜, 你回来了, 路上辛苦了。我来拿箱子吧。",es:"Lin Na, ¡ya volviste! Qué viaje tan largo. Deja que lleve tu maleta.",en:"Lin Na, you're back — long trip! Let me take your suitcase."},
{s:"林娜",zh:"力波, 你等了多长时间?",es:"Libo, ¿cuánto esperaste?",en:"Libo, how long did you wait?"},
{s:"丁力波",zh:"我今天在外边办事很顺利, 路上也不堵车, 两点十分就到了。",es:"Hoy mis gestiones salieron muy bien y no había atasco: llegué a las 2:10.",en:"My errands went smoothly and there was no traffic — I got here at 2:10."},
{s:"林娜",zh:"真不好意思, 让你等了五十分钟!",es:"¡Cuánto lo siento, te hice esperar cincuenta minutos!",en:"I'm so sorry — I made you wait fifty minutes!"},
{s:"丁力波",zh:"没关系。我用手机上了一会儿网, 后来跟坐在旁边的一个学生聊了半小时天儿。我们聊得很高兴。",es:"No pasa nada: navegué un rato con el móvil y luego charlé media hora con un estudiante sentado al lado. Lo pasamos muy bien.",en:"No problem — I browsed on my phone a while, then chatted half an hour with a student next to me. We had a nice talk."},
{s:"林娜",zh:"你总是能遇到聊天儿的人。",es:"Tú siempre encuentras con quién charlar.",en:"You always find someone to chat with."},
{s:"丁力波",zh:"我喜欢听北京人说普通话。咱们从这边走吧, 我把车停在地下停车场了。",es:"Me gusta oír a los pekineses hablar mandarín. Vamos por aquí; aparqué en el estacionamiento subterráneo.",en:"I like hearing Beijingers speak Mandarin. Let's go this way — I parked in the underground lot."},
{s:"林娜",zh:"好的。等一下, 我把帽子放到箱子里去。",es:"Vale. Espera, guardo el gorro en la maleta.",en:"OK. Hold on — let me put my hat in the suitcase."},
{s:"丁力波",zh:"你今天坐火车坐了多长时间?",es:"¿Cuánto duró el viaje en tren hoy?",en:"How long was your train ride today?"},
{s:"林娜",zh:"大概五个小时。没想到高铁这么快!",es:"Unas cinco horas. ¡No imaginaba que el tren de alta velocidad fuera tan rápido!",en:"About five hours. I didn't expect high-speed rail to be this fast!"},
{s:"丁力波",zh:"是啊。以前从上海来北京, 火车要坐十几个小时。",es:"Sí; antes, de Shanghai a Beijing el tren tardaba más de diez horas.",en:"Yeah — the train from Shanghai to Beijing used to take over ten hours."},
{s:"林娜",zh:"现在坐高铁又快又舒服。",es:"Ahora el tren rápido es veloz y cómodo.",en:"Now the high-speed train is fast and comfortable."},
{s:"丁力波",zh:"你在车上做什么了?",es:"¿Qué hiciste durante el viaje?",en:"What did you do on the train?"},
{s:"林娜",zh:"我先睡了两个小时觉, 又看了一个小时书。后来听了一会儿音乐, 还上了一会儿网。",es:"Primero dormí dos horas y leí una hora. Luego escuché música un rato y navegué otro poco.",en:"First I slept two hours and read for an hour. Then I listened to music and went online for a bit."},
{s:"丁力波",zh:"高铁上有无线网吗?",es:"¿Hay Wi-Fi en el tren?",en:"Is there Wi-Fi on the train?"},
{s:"林娜",zh:"有, 上网很方便。",es:"Sí, es muy cómodo conectarse.",en:"Yes — getting online is easy."},
{s:"丁力波",zh:"对了, 昨天我们宿舍的网络坏了, 断了五个小时。这么长时间不能上网, 真是太无聊了。",es:"Por cierto, ayer se estropeó la red del dormitorio: cinco horas sin conexión. ¡Qué aburrimiento tan grande!",en:"By the way, our dorm internet broke yesterday — down for five hours. That long without internet is so boring."},
{s:"林娜",zh:"你昨天应该坐高铁去上海接我, 这五个小时都可以上网。",es:"Ayer debiste tomar el tren a Shanghai a recogerme: esas cinco horas habrías tenido internet.",en:"You should've taken the train to Shanghai to fetch me — you'd have had internet those five hours."}]}]},
{l:14,t:"租的比买的便宜多了",tes:"Alquilar es mucho más barato que comprar",ten:"Renting is much cheaper than buying",parts:[
{ies:"Ding Libo, Lin Na y Ma Dawei discuten fuera del dormitorio cuando aparece Wang Xiaoyun.",ien:"Ding Libo, Lin Na and Ma Dawei are talking outside the dorm when Wang Xiaoyun shows up.",lines:[
{s:"王小云",zh:"林娜、大为、力波, 你们都在。今天天气不错。",es:"Lin Na, Dawei, Libo, están todos. Qué buen tiempo hace hoy.",en:"Lin Na, Dawei, Libo — you're all here. Nice weather today."},
{s:"丁力波",zh:"是啊, 今天比昨天暖和。小云, 好久没见到你了, 今天怎么有时间过来?",es:"Sí, hoy hace más calor que ayer. Xiaoyun, hacía mucho que no te veíamos, ¿cómo es que hoy tienes tiempo?",en:"Yes, warmer than yesterday. Xiaoyun, long time no see — how come you have time today?"},
{s:"王小云",zh:"我来看看你们啊。林娜, 宋华让我把这本书带给你。他说书上有你要的那个话剧。",es:"Vine a verlos. Lin Na, Song Hua me pidió traerte este libro; dice que trae la obra de teatro que buscabas.",en:"I came to see you all. Lin Na, Song Hua asked me to bring you this book — it has the play you wanted."},
{s:"林娜",zh:"替我谢谢宋华。我在图书馆查了很长时间, 没查到这个话剧。",es:"Dale las gracias de mi parte. Busqué mucho tiempo en la biblioteca y no la encontraba.",en:"Thank him for me. I searched the library forever and couldn't find it."},
{s:"王小云",zh:"听说今年咱们学校的留学生晚会六月才开, 去年是五月。你们班要表演什么节目?",es:"Dicen que la gala de estudiantes extranjeros será recién en junio; el año pasado fue en mayo. ¿Qué número presentará tu clase?",en:"I hear this year's international students' gala isn't until June — last year it was May. What's your class performing?"},
{s:"马大为",zh:"你问得好, 我们商量了两天, 还没决定呢。你有什么建议?",es:"Buena pregunta: llevamos dos días discutiéndolo y aún no decidimos. ¿Alguna sugerencia?",en:"Good question — we've discussed it for two days and still haven't decided. Any suggestions?"},
{s:"王小云",zh:"你们可以跳舞或者表演太极拳。",es:"Podrían bailar o hacer una demostración de taichí.",en:"You could dance or perform tai chi."},
{s:"丁力波",zh:"我觉得打太极拳比跳舞有意思。",es:"El taichí me parece más interesante que bailar.",en:"I think tai chi is more interesting than dancing."},
{s:"林娜",zh:"可是打太极拳太慢了, 跳舞比打太极拳热闹。",es:"Pero el taichí es muy lento; bailar es más animado.",en:"But tai chi is too slow — dancing is livelier."},
{s:"王小云",zh:"这样吧, 你们表演一个汉语话剧, 怎么样?",es:"¿Y si presentan una obra de teatro en chino?",en:"How about this: perform a play in Chinese?"},
{s:"丁力波",zh:"是个好主意。我们是汉语专业的学生, 应该表演汉语节目。",es:"Buena idea. Somos estudiantes de chino; deberíamos presentar algo en chino.",en:"Good idea. We're Chinese majors — we should do a Chinese-language act."},
{s:"马大为",zh:"别表演话剧了, 太难了! 我们可以唱中文歌, 唱歌比演话剧容易。",es:"¡Teatro no, es dificilísimo! Cantemos canciones en chino; es más fácil que actuar.",en:"Not a play — too hard! Let's sing Chinese songs; singing is easier than acting."},
{s:"丁力波",zh:"可是晚会上唱歌的节目很多, 唱好也不容易。再说, 演话剧还能提高我们的口语水平。",es:"Pero en la gala habrá muchos números de canto, y cantar bien tampoco es fácil. Además, actuar mejora nuestro chino oral.",en:"But there'll be lots of singing acts, and singing well isn't easy either. Besides, acting improves our spoken Chinese."},
{s:"王小云",zh:"是啊, 你们可以写一个小话剧, 写你们在中国的故事, 多有意思啊!",es:"Sí: escriban una obrita sobre sus vivencias en China. ¡Qué interesante sería!",en:"Right — write a short play about your experiences in China. How interesting would that be!"},
{s:"林娜",zh:"你们说得对, 我同意。力波, 你的汉语比我好, 你来写吧。",es:"Tienen razón, estoy de acuerdo. Libo, tu chino es mejor que el mío: escribe tú.",en:"You're right, I agree. Libo, your Chinese is better than mine — you write it."},
{s:"丁力波",zh:"我试试。我想写一个留学生学太极拳的故事。小云, 你可以跟我一起写吗?",es:"Lo intento. Quiero escribir la historia de un estudiante extranjero que aprende taichí. Xiaoyun, ¿lo escribes conmigo?",en:"I'll try. I want to write about a foreign student learning tai chi. Xiaoyun, will you co-write it?"},
{s:"王小云",zh:"没问题。对了, 陆雨平是记者, 他的写作水平比我高, 咱们找他来商量商量吧。",es:"Claro. Ah, Lu Yuping es periodista y escribe mejor que yo: consultémosle.",en:"Sure. Oh — Lu Yuping is a reporter and writes better than I do; let's ask him."},
{s:"丁力波",zh:"对啊, 写剧本他一定又快又好, 比咱们强。我给他打电话。",es:"Cierto; el guión le saldrá rápido y bien, mejor que a nosotros. Lo llamo.",en:"Right — he'd write the script fast and well, better than us. I'll call him."}]},
{ies:"Lin Na y Ding Libo preparan los trajes; luego van a la tienda de alquiler de ropa.",ien:"Lin Na and Ding Libo sort out costumes, then visit a costume rental shop.",lines:[
{s:"林娜",zh:"这套太极拳服装是谁的?",es:"¿De quién es este traje de taichí?",en:"Whose tai chi outfit is this?"},
{s:"丁力波",zh:"是我的。你觉得怎么样?",es:"Mío. ¿Qué te parece?",en:"Mine. What do you think?"},
{s:"林娜",zh:"很合适。咱们还需要四套太极拳服装和一件旗袍。",es:"Te queda bien. Aún necesitamos cuatro trajes de taichí y un qipao.",en:"It fits well. We still need four tai chi outfits and a qipao."},
{s:"丁力波",zh:"小云有一件旗袍, 咱们可以借她的。",es:"Xiaoyun tiene un qipao; podemos pedírselo prestado.",en:"Xiaoyun has a qipao — we can borrow hers."},
{s:"林娜",zh:"她那件是短的, 我想要一件长的。咱们应该去哪儿买呢?",es:"El suyo es corto y yo quiero uno largo. ¿Dónde lo compramos?",en:"Hers is short and I want a long one. Where should we buy it?"},
{s:"丁力波",zh:"听说电影学院旁边有不少出租服装的商店, 咱们可以去租服装。",es:"Dicen que junto a la Academia de Cine hay varias tiendas que alquilan trajes; podemos alquilarlos.",en:"There are several costume rental shops near the Film Academy — we could rent."},
{s:"林娜",zh:"好啊! 租的比买的便宜多了。下午咱们去看看。",es:"¡Genial! Alquilar es mucho más barato que comprar. Vamos esta tarde.",en:"Great! Renting is way cheaper than buying. Let's go this afternoon."},
{s:"丁力波",zh:"这两件太极拳服装的式样都很合适。你觉得哪件好? 白的还是黑的?",es:"Estos dos trajes de taichí tienen buen estilo. ¿Cuál prefieres, el blanco o el negro?",en:"Both these tai chi outfits look right. Which is better — white or black?"},
{s:"马大为",zh:"都很好。",es:"Los dos están bien.",en:"Both are fine."},
{s:"林娜",zh:"我看, 表演的时候, 穿白的比穿黑的漂亮。",es:"Para la función, el blanco lucirá más que el negro.",en:"For the show, white will look nicer than black."},
{s:"丁力波",zh:"好, 就要白的。这儿的旗袍怎么样?",es:"Vale, el blanco. ¿Y los qipao de aquí?",en:"OK, white it is. How are the qipaos here?"},
{s:"林娜",zh:"式样太多了, 我真不知道该选哪件。",es:"Hay tantos modelos que no sé cuál elegir.",en:"So many styles — I really don't know which to pick."},
{s:"丁力波",zh:"我帮你看看。这件绿的怎么样?",es:"Te ayudo. ¿Qué tal este verde?",en:"Let me help. How about this green one?"},
{s:"林娜",zh:"这件颜色太深了, 我想要浅一点儿的。",es:"Es de color muy oscuro; quiero uno más claro.",en:"The color's too dark — I'd like something lighter."},
{s:"丁力波",zh:"这件红的怎么样? 红的是不是比绿的漂亮?",es:"¿Y este rojo? ¿No es más bonito que el verde?",en:"What about this red one? Isn't red prettier than green?"},
{s:"马大为",zh:"红的不比绿的漂亮。我看红的绿的都行。",es:"El rojo no es más bonito que el verde; para mí, ambos valen.",en:"Red isn't prettier than green — I think either works."},
{s:"林娜",zh:"这件红的颜色不错, 可是短了点儿, 我想要长点儿的。",es:"El rojo tiene buen color, pero es algo corto; quiero uno más largo.",en:"The red one's color is nice but it's a bit short — I want it longer."},
{s:"丁力波",zh:"你看这件, 比那件长两公分, 颜色也不深。",es:"Mira este: es dos centímetros más largo y el color no es oscuro.",en:"Look at this one — two centimeters longer, and not too dark."},
{s:"林娜",zh:"可是这件是棉的, 我想要真丝的。",es:"Pero es de algodón y yo lo quiero de seda pura.",en:"But it's cotton — I want pure silk."},
{s:"马大为",zh:"你们慢慢看吧, 我先去一下卫生间。",es:"Sigan mirando con calma; yo voy un momento al baño.",en:"You two take your time — I'm off to the bathroom."}]}]},
{l:15,t:"中国画跟油画不一样",tes:"Las pinturas chinas y las pinturas al óleo son diferentes",ten:"Chinese painting is different from oil painting",parts:[
{ies:"Ding Libo y Lin Na están en la entrada de una galería de arte.",ien:"Ding Libo and Lin Na are at the entrance of an art gallery.",lines:[
{s:"丁力波",zh:"咱们来早了, 美术馆还没开门呢。",es:"Llegamos temprano: la galería todavía no abre.",en:"We're early — the gallery isn't open yet."},
{s:"林娜",zh:"来早了比来晚了好。今天咱们得好好儿参观参观。我上次来晚了, 看了两个小时, 二层的展览没看完。",es:"Mejor temprano que tarde. Hoy hay que visitarla a fondo: la última vez llegué tarde, estuve dos horas y no terminé la segunda planta.",en:"Better early than late. Today we should see it properly — last time I came late, spent two hours, and didn't finish the second floor."},
{s:"丁力波",zh:"你真喜欢中国画!",es:"¡De verdad te encanta la pintura china!",en:"You really love Chinese painting!"},
{s:"林娜",zh:"是啊, 我非常喜欢中国画, 特别是花鸟画。",es:"Sí, muchísimo; sobre todo la pintura de flores y pájaros.",en:"Yes, very much — especially flower-and-bird painting."},
{s:"丁力波",zh:"我跟你一样, 也很喜欢中国画。从我十岁开始, 妈妈就教我画中国画。你说, 我画了多少年了?",es:"Igual que tú, me encanta. Desde los diez años mi mamá me enseña a pintarla. ¿Cuántos años llevo pintando?",en:"Same as you — I love it. My mom's taught me since I was ten. Guess how many years I've painted?"},
{s:"林娜",zh:"你今年多大?",es:"¿Cuántos años tienes?",en:"How old are you?"},
{s:"丁力波",zh:"我比你哥哥小六岁。",es:"Seis años menos que tu hermano.",en:"Six years younger than your brother."},
{s:"林娜",zh:"啊, 已经画了十一年了! 我真不知道您还是一位“老画家”。",es:"¡Once años ya! No sabía que era usted todo un «viejo pintor».",en:"Wow, eleven years already! I had no idea you were an 'old master'."},
{s:"丁力波",zh:"不敢当。你哥哥跟你一样喜欢中国画吗?",es:"No merezco tanto. ¿A tu hermano le gusta la pintura china como a ti?",en:"You flatter me. Does your brother like Chinese painting like you?"},
{s:"林娜",zh:"他跟我不一样, 他喜欢油画。你爸爸教中文, 他也喜欢中国画吗?",es:"Él no; prefiere el óleo. Tu papá enseña chino, ¿también le gusta la pintura china?",en:"He's different — he likes oils. Your dad teaches Chinese — does he like Chinese painting too?"},
{s:"丁力波",zh:"他跟咱们都不一样。他对油画和中国画都不太感兴趣, 只喜欢唱京剧。",es:"Él es distinto de nosotros: ni el óleo ni la pintura china le interesan mucho; solo le gusta cantar ópera de Beijing.",en:"He's different from us both — not much into oils or Chinese painting; he only likes singing Beijing opera."},
{s:"林娜",zh:"他一定唱得很好。",es:"Seguro canta muy bien.",en:"He must sing very well."},
{s:"丁力波",zh:"他唱京剧跟我画中国画一样, 马马虎虎。",es:"Canta ópera igual que yo pinto: así así.",en:"His opera is like my painting — so-so."},
{s:"林娜",zh:"你太谦虚了! 你学了那么长时间, 一定画得很好。对了, 回国以前, 我想买一幅中国画。你知道的画家比我多, 大画家的画儿是不是很贵?",es:"¡Qué modesto! Con tantos años, seguro pintas muy bien. Por cierto, antes de volver a mi país quiero comprar una pintura china. Tú conoces más pintores que yo: ¿las obras de los grandes maestros son muy caras?",en:"You're too modest! After so long you must paint well. By the way, before going home I want to buy a Chinese painting. You know more painters than I do — are famous painters' works expensive?"},
{s:"丁力波",zh:"当然很贵。",es:"Claro que sí.",en:"Of course they are."},
{s:"林娜",zh:"能买到便宜点儿的吗? 力波, 你总是比我有办法。",es:"¿Se puede conseguir algo más barato? Libo, tú siempre tienes más recursos que yo.",en:"Can I get something cheaper? Libo, you always have more tricks than me."},
{s:"丁力波",zh:"我认识一位“老画家”, 他的画儿比大画家的便宜多了。",es:"Conozco a un «viejo pintor» cuyas obras son mucho más baratas que las de los maestros.",en:"I know an 'old master' whose paintings are much cheaper than the famous ones'."},
{s:"林娜",zh:"这位老画家是谁? 可以让我认识认识吗?",es:"¿Quién es? ¿Me lo presentas?",en:"Who is he? Can you introduce me?"},
{s:"丁力波",zh:"可以, “远在天边, 近在眼前”, 他就是丁力波啊! 我可以把我自己的画儿送给你。",es:"Claro: «lejos en el horizonte, cerca ante tus ojos»… ¡soy yo! Puedo regalarte una pintura mía.",en:"Sure — 'far at the horizon, right before your eyes' — it's me! I can give you one of my own paintings."}]},
{ies:"En la galería de arte.",ien:"Inside the art gallery.",lines:[
{s:"丁力波",zh:"刚才你去哪儿了?",es:"¿Adónde fuiste hace un momento?",en:"Where did you go just now?"},
{s:"林娜",zh:"我到前面去了, 这些我已经看完了。",es:"Fui adelante; estas ya las terminé de ver.",en:"I went ahead — I've finished looking at these."},
{s:"丁力波",zh:"你比我看得快多了。",es:"Miras mucho más rápido que yo.",en:"You look much faster than I do."},
{s:"林娜",zh:"咱们已经看了一个半小时了, 二层的还没有看呢。现在是不是上楼去?",es:"Llevamos ya hora y media y aún no vimos la segunda planta. ¿Subimos ahora?",en:"We've been here an hour and a half and haven't seen upstairs. Shall we go up now?"},
{s:"丁力波",zh:"好吧, 咱们坐电梯上去。",es:"Vale, subamos en ascensor.",en:"OK, let's take the elevator up."},
{s:"林娜",zh:"你觉得中国画跟油画一样不一样?",es:"¿Crees que la pintura china y el óleo son iguales o diferentes?",en:"Do you think Chinese painting and oil painting are the same or different?"},
{s:"丁力波",zh:"当然一样, 都是画儿啊。",es:"Claro que iguales: ¡ambas son pinturas!",en:"The same, of course — they're both paintings!"},
{s:"林娜",zh:"别开玩笑。",es:"No bromees.",en:"Stop joking."},
{s:"丁力波",zh:"我没有开玩笑, 我是说中国画跟油画一样美。当然, 它们也有不一样的地方。",es:"No bromeo: digo que la pintura china es tan bella como el óleo. Claro que también tienen diferencias.",en:"I'm not joking — I mean Chinese painting is as beautiful as oils. Of course they differ too."},
{s:"林娜",zh:"中国画你比我懂得多, 你说说哪儿不一样。",es:"Tú sabes de pintura china más que yo: dime en qué se diferencian.",en:"You know Chinese painting better than me — tell me how they differ."},
{s:"丁力波",zh:"你找对人了, 别忘了我是“老画家”啊。中国画主要用墨和水画, 油画一定要用油彩画。",es:"Preguntaste a la persona indicada: recuerda que soy el «viejo pintor». La pintura china usa sobre todo tinta y agua; el óleo, necesariamente óleos.",en:"You asked the right person — remember, I'm the 'old master'. Chinese painting mainly uses ink and water; oil painting must use oil paints."},
{s:"林娜",zh:"是不一样。",es:"Sí que son distintas.",en:"They are different."},
{s:"丁力波",zh:"还有, 你看这幅徐悲鸿的画儿, 画家只画了一匹马, 没有画别的。",es:"Además, mira esta obra de Xu Beihong: el pintor pintó solo un caballo, nada más.",en:"Also, look at this Xu Beihong — he painted just one horse, nothing else."},
{s:"林娜",zh:"可是我觉得还有别的东西。我好像看到那匹马往咱们这儿跑来了。",es:"Pero yo siento que hay algo más: como si el caballo galopara hacia nosotros.",en:"But I feel there's something more — as if that horse were galloping toward us."},
{s:"丁力波",zh:"你说得对。你是不是觉得它跑得非常快, 好像还有风?",es:"Exacto. ¿No te parece que corre rapidísimo, como si hasta soplara viento?",en:"Exactly. Doesn't it seem to run incredibly fast, as if there's wind?"},
{s:"林娜",zh:"是啊。这就跟齐白石画的虾一样, 画家没有画水, 可是我觉得那些虾在水里游来游去, 像真的一样!",es:"Sí. Igual que los camarones de Qi Baishi: no pintó agua, pero parecen nadar de un lado a otro, ¡como de verdad!",en:"Yes — just like Qi Baishi's shrimp: he painted no water, yet they seem to swim around, like real ones!"},
{s:"丁力波",zh:"对。你看, 在中国画上还有书法, 但是在油画上常常看不到字。",es:"Así es. Y fíjate: la pintura china lleva caligrafía; en el óleo rara vez ves caracteres.",en:"Right. And see — Chinese paintings include calligraphy, while on oil paintings you rarely see writing."},
{s:"林娜",zh:"中国画真的跟油画很不一样。谢谢你的介绍, 老画家就是老画家。",es:"La pintura china es realmente muy distinta del óleo. Gracias por la explicación: el viejo pintor no defrauda.",en:"Chinese painting really is different from oils. Thanks for the guide — the old master lives up to his name."}]}]},
{l:16,t:"我是五岁开始学游泳的",tes:"Tenía cinco años cuando aprendí a nadar",ten:"I started learning to swim at five",parts:[
{ies:"Song Hua practica natación en la piscina; ve a Lin Na acercarse.",ien:"Song Hua is practicing at the pool when Lin Na comes over.",lines:[
{s:"宋华",zh:"林娜, 你也来了!",es:"¡Lin Na, tú también viniste!",en:"Lin Na, you're here too!"},
{s:"林娜",zh:"我来了一会儿了。宋华, 我真不知道你游泳游得这么好。",es:"Llegué hace un rato. Song Hua, no sabía que nadaras tan bien.",en:"I've been here a while. Song Hua, I had no idea you swam this well."},
{s:"宋华",zh:"哪里。我知道你游得也很好。最近你常来游泳吗?",es:"Qué va. Sé que tú también nadas muy bien. ¿Vienes seguido últimamente?",en:"Not at all. I know you swim well too. Have you been coming often lately?"},
{s:"林娜",zh:"是啊, 我觉得我该减肥了, 所以每天都来游一个小时。",es:"Sí; creo que debo adelgazar, así que nado una hora cada día.",en:"Yes — I think I need to lose weight, so I swim an hour every day."},
{s:"宋华",zh:"每天锻炼身体很重要。可是你为什么觉得现在需要减肥呢?",es:"Ejercitarse a diario es importante. Pero ¿por qué crees que necesitas adelgazar?",en:"Daily exercise is important. But why do you think you need to lose weight?"},
{s:"林娜",zh:"因为我现在吃得太多了, 所以体重比以前增加了很多, 人也胖了。你说, 能不减肥吗? 宋华, 你还喜欢什么运动?",es:"Como ahora como demasiado, mi peso subió mucho y engordé. ¿Cómo no voy a ponerme a dieta? Song Hua, ¿qué otros deportes te gustan?",en:"I eat too much now, so I've gained a lot and gotten plump. How could I not diet? Song Hua, what other sports do you like?"},
{s:"宋华",zh:"我还喜欢踢足球、跑步。当然, 我最喜欢的还是游泳。",es:"También el fútbol y correr. Pero mi favorito sigue siendo la natación.",en:"I also like soccer and jogging. But swimming is still my favorite."},
{s:"林娜",zh:"你是多大开始学游泳的?",es:"¿A qué edad empezaste a nadar?",en:"How old were you when you learned to swim?"},
{s:"宋华",zh:"我是五岁开始学游泳的。你呢?",es:"Empecé a los cinco años. ¿Y tú?",en:"I started at five. You?"},
{s:"林娜",zh:"三岁, 在游泳班学的。",es:"A los tres, en una clase de natación.",en:"Three — in a swimming class."},
{s:"宋华",zh:"我跟你不一样, 我不是在游泳班学的, 是跟我爸爸学的。我们游泳队里有的队员也是跟爸爸或者哥哥学的。",es:"Yo no: no aprendí en clase, sino con mi papá. En nuestro equipo algunos también aprendieron con su padre o su hermano.",en:"Different from you — I didn't learn in a class but from my dad. Some of our team members also learned from their dads or brothers."},
{s:"林娜",zh:"你是说, 他们的爸爸或者哥哥在游泳池教他们游泳?",es:"¿O sea que sus padres o hermanos les enseñaron en la piscina?",en:"You mean their dads or brothers taught them at the pool?"},
{s:"宋华",zh:"也不一定。他们有的是从农村来的, 那儿以前没有游泳池, 也没有游泳教练。",es:"No siempre. Algunos vienen del campo, donde antes no había piscina ni entrenador.",en:"Not necessarily. Some come from the countryside, where there used to be no pools or coaches."},
{s:"林娜",zh:"那他们是怎么学会游泳的呢?",es:"¿Y cómo aprendieron a nadar?",en:"Then how did they learn to swim?"},
{s:"宋华",zh:"他们是自己在河里学的。当然, 参加游泳队以后, 又跟教练学了很多。",es:"Solos, en el río. Claro que al entrar al equipo aprendieron mucho más con el entrenador.",en:"By themselves in the river. Of course, after joining the team they learned a lot from the coach."},
{s:"林娜",zh:"他们游得跟你一样好吗?",es:"¿Nadan tan bien como tú?",en:"Do they swim as well as you?"},
{s:"宋华",zh:"有的游得比我好多了! 下个月你来看我们的比赛吧。",es:"¡Algunos mucho mejor que yo! Ven a vernos competir el mes que viene.",en:"Some swim way better than me! Come watch our meet next month."},
{s:"林娜",zh:"好, 我一定来给你们加油。",es:"Sí, iré sin falta a animarlos.",en:"I'll definitely come cheer you on."}]},
{ies:"Lu Yuping llama a Ma Dawei.",ien:"Lu Yuping calls Ma Dawei.",lines:[
{s:"陆雨平",zh:"喂, 是大为吗? 在忙什么呢?",es:"¿Aló, Dawei? ¿Qué andas haciendo?",en:"Hello, Dawei? What are you up to?"},
{s:"马大为",zh:"我在看电视呢。",es:"Estoy viendo la tele.",en:"I'm watching TV."},
{s:"陆雨平",zh:"现在看电视? 是什么好节目啊?",es:"¿Tele a esta hora? ¿Qué programa tan bueno es?",en:"TV right now? What's so good on?"},
{s:"马大为",zh:"是足球赛。你这个足球迷没在看吗?",es:"Un partido de fútbol. ¿Tú, tan futbolero, no lo estás viendo?",en:"A soccer match. You're the soccer fan — aren't you watching?"},
{s:"陆雨平",zh:"没有, 我正在写东西呢。谁跟谁比赛?",es:"No, estoy escribiendo algo. ¿Quién juega contra quién?",en:"No, I'm in the middle of writing. Who's playing whom?"},
{s:"马大为",zh:"市大学生队跟留学生队比赛。",es:"El equipo universitario de la ciudad contra el de estudiantes extranjeros.",en:"The city university team versus the international students' team."},
{s:"陆雨平",zh:"比赛一定很精彩。我看留学生队不比市大学生队差。",es:"Debe de estar buenísimo. Para mí, los extranjeros no son peores que los universitarios.",en:"Must be exciting. I'd say the international team is no worse than the city team."},
{s:"马大为",zh:"是啊, 精彩极了! 上半场的比分是0比0, 两队都没有进球。现在是下半场, 只剩一刻钟了。对了, 你找我有什么事儿吗?",es:"¡Sí, emocionante! La primera mitad quedó 0-0, nadie marcó. Va la segunda mitad y solo queda un cuarto de hora. Ah, ¿para qué me llamabas?",en:"Yes, thrilling! First half ended 0–0, no goals. It's the second half now with only fifteen minutes left. Oh — what did you need?"},
{s:"陆雨平",zh:"是这样的, 我今天下午给你打了两个电话, 你都没接。",es:"Es que esta tarde te llamé dos veces y no contestaste.",en:"Well, I called you twice this afternoon and you didn't pick up."},
{s:"马大为",zh:"是吗? 你是下午几点打的?",es:"¿En serio? ¿A qué hora llamaste?",en:"Really? What time did you call?"},
{s:"陆雨平",zh:"三点。那时候你在上课吗?",es:"A las tres. ¿Estabas en clase?",en:"Three o'clock. Were you in class then?"},
{s:"马大为",zh:"没在上课。我在做什么呢? 对了, 我正在图书馆借书, 所以没带手机。",es:"No… ¿qué hacía? Ah, sí: estaba sacando libros en la biblioteca y no llevaba el móvil.",en:"No… what was I doing? Right — I was borrowing books at the library and didn't have my phone."},
{s:"陆雨平",zh:"我打电话想问问你, 下星期六我们足球队跟银行队比赛, 你还能当我们的外援吗?",es:"Te llamaba para preguntarte: el próximo sábado nuestro equipo juega contra el del banco, ¿puedes ser de nuevo nuestro refuerzo?",en:"I called to ask: next Saturday our team plays the bank's team — can you be our foreign reinforcement again?"},
{s:"马大为",zh:"我……啊, 进了, 好球! 1比0。留学生队进了一球, 太好了! 不好意思, 刚才你说下周六比赛吗? 几点开始?",es:"Yo… ¡Ah, gol, golazo! 1-0, ¡marcaron los extranjeros, genial! Perdona, ¿decías que el partido es el sábado? ¿A qué hora?",en:"I… ah, GOAL! What a shot! 1–0, the international team scored — awesome! Sorry, you said the match is next Saturday? What time?"},
{s:"陆雨平",zh:"上午九点开始, 在市体育馆。",es:"A las nueve de la mañana, en el estadio municipal.",en:"Nine a.m., at the city stadium."},
{s:"马大为",zh:"没问题, 我能参加。",es:"Sin problema, puedo jugar.",en:"No problem, I can play."},
{s:"陆雨平",zh:"还有, 这个星期四晚上七点我们球队在你们学校练习, 你能来吗?",es:"Otra cosa: este jueves a las siete el equipo entrena en tu universidad, ¿puedes venir?",en:"Also, this Thursday at 7 pm our team practices at your school — can you come?"},
{s:"马大为",zh:"七点? 恐怕不行, 我在上汉语水平考试辅导课呢, 七点半才下课。我下课以后去找你们, 怎么样?",es:"¿A las siete? Me temo que no: tengo clase de preparación del HSK y salgo a las siete y media. ¿Los alcanzo después de clase?",en:"Seven? Afraid not — I'm in HSK prep class until seven thirty. How about I join you after class?"},
{s:"陆雨平",zh:"好的。",es:"Vale.",en:"OK."},
{s:"马大为",zh:"又进了!",es:"¡Otro gol!",en:"Another goal!"},
{s:"陆雨平",zh:"谁又进了? 哪个队赢了?",es:"¿Quién marcó ahora? ¿Qué equipo ganó?",en:"Who scored this time? Which team won?"},
{s:"马大为",zh:"这次是留学生队帮助市大学生队进了一个球。最后的比分是1比1。",es:"Esta vez los extranjeros «ayudaron» al equipo de la ciudad con un autogol. Final: 1-1.",en:"This time the international team 'helped' the city team score. Final score: 1–1."}]}]},
{l:17,t:"你看过京剧没有",tes:"Has visto alguna vez la Ópera de Beijing",ten:"Have you ever seen Beijing opera",parts:[
{ies:"Song Hua y Lin Na están en una cafetería.",ien:"Song Hua and Lin Na are at a café.",lines:[
{s:"宋华",zh:"林娜, 你看过京剧没有?",es:"Lin Na, ¿has visto la ópera de Beijing?",en:"Lin Na, have you ever seen Beijing opera?"},
{s:"林娜",zh:"没有。来中国以后, 我听过两次音乐会, 看过一次杂技, 还没看过京剧。",es:"No. Desde que llegué a China fui a dos conciertos y una función de acrobacia, pero ópera todavía no.",en:"No. Since coming to China I've been to two concerts and one acrobatics show, but no opera yet."},
{s:"宋华",zh:"你是在哪儿看的杂技?",es:"¿Dónde viste la acrobacia?",en:"Where did you see the acrobatics?"},
{s:"林娜",zh:"新华剧院, 是学校组织我们留学生去看的。",es:"En el Teatro Xinhua; lo organizó la universidad para los estudiantes extranjeros.",en:"At the Xinhua Theater — the school organized it for us international students."},
{s:"宋华",zh:"你去过国家大剧院吗?",es:"¿Conoces el Gran Teatro Nacional?",en:"Have you been to the National Centre for the Performing Arts?"},
{s:"林娜",zh:"我去天安门的时候看到过, 但是没进去过。",es:"Lo vi cuando fui a Tian'anmen, pero nunca entré.",en:"I saw it when I went to Tian'anmen, but I've never been inside."},
{s:"宋华",zh:"想不想去那儿看一次京剧? 我有两张票。",es:"¿Te gustaría ver allí una ópera de Beijing? Tengo dos entradas.",en:"Want to see a Beijing opera there? I have two tickets."},
{s:"林娜",zh:"当然想去。",es:"Claro que sí.",en:"Of course I do."},
{s:"宋华",zh:"这个星期六晚上七点在那儿演京剧的《红楼梦》。你听说过《红楼梦》吧?",es:"Este sábado a las siete representan la versión de ópera de «Sueño en el pabellón rojo». La conoces, ¿no?",en:"This Saturday at seven they're performing the opera version of Dream of the Red Chamber. You've heard of it, right?"},
{s:"林娜",zh:"听说过。《红楼梦》是中国著名的古典小说, 我看过一遍, 是英语版的。",es:"Sí: es la famosa novela clásica china. La leí una vez, en versión inglesa.",en:"I have — it's the famous classical Chinese novel. I read it once, in English."},
{s:"宋华",zh:"你喜欢这部小说吗?",es:"¿Te gustó la novela?",en:"Did you like the novel?"},
{s:"林娜",zh:"很喜欢, 我觉得小说里的爱情故事非常感人。",es:"Mucho; su historia de amor me pareció conmovedora.",en:"Very much — I found its love story deeply moving."},
{s:"宋华",zh:"你说的是贾宝玉和林黛玉的爱情故事吧?",es:"Hablas del amor entre Jia Baoyu y Lin Daiyu, ¿verdad?",en:"You mean the love story of Jia Baoyu and Lin Daiyu, right?"},
{s:"林娜",zh:"是啊, 宝玉很爱黛玉, 黛玉也爱宝玉。可是他家里人一定要宝玉跟别的姑娘结婚。他们非常痛苦, 黛玉很快就病死了。最后宝玉也离开了家。",es:"Sí: Baoyu ama a Daiyu y ella a él, pero su familia lo obliga a casarse con otra. Sufren muchísimo; Daiyu enferma y muere pronto, y al final Baoyu abandona el hogar.",en:"Yes — Baoyu loves Daiyu and she loves him, but his family forces him to marry another girl. They suffer terribly; Daiyu soon falls ill and dies, and in the end Baoyu leaves home."},
{s:"宋华",zh:"他们的故事你记得真清楚! 你再看一次京剧版的, 看看你喜欢哪个。",es:"¡Qué bien recuerdas su historia! Ve ahora la versión de ópera y compara cuál te gusta más.",en:"You remember it so clearly! Now watch the opera version and see which you prefer."},
{s:"林娜",zh:"我真想看京剧的《红楼梦》。星期六下午你来找我吧。",es:"De verdad quiero verla. Ven a buscarme el sábado por la tarde.",en:"I really want to see it. Come get me Saturday afternoon."}]},
{ies:"Acaban de ver la ópera y están en la sala de descanso del teatro.",ien:"They've just seen the opera and are in the theater lounge.",lines:[
{s:"宋华",zh:"你觉得京剧的《红楼梦》怎么样?",es:"¿Qué te pareció la versión de ópera?",en:"What did you think of the opera version?"},
{s:"林娜",zh:"跟小说一样好, 两个主角演得好极了。演员们的服装也特别漂亮。",es:"Tan buena como la novela; los dos protagonistas actuaron de maravilla y el vestuario era precioso.",en:"As good as the novel — the two leads were superb, and the costumes were gorgeous."},
{s:"宋华",zh:"他们唱的你能听懂一些吗?",es:"¿Entendiste algo de lo que cantaban?",en:"Could you understand some of the singing?"},
{s:"林娜",zh:"还不能。虽然他们唱的我没听懂, 但是我觉得京剧的音乐特别好听。",es:"Todavía no. Aunque no entendí lo que cantaban, la música me pareció bellísima.",en:"Not yet. Though I didn't understand the lyrics, I found the music really beautiful."},
{s:"宋华",zh:"是啊, 很多外国朋友都喜欢京剧, 一些外国学生还到北京来学京剧。现在他们有的人会唱京剧, 有的人还会演京剧。",es:"Sí: a muchos extranjeros les encanta; algunos vienen a Beijing a estudiarla, y ya hay quienes la cantan e incluso la actúan.",en:"Yes — many foreigners love it; some come to Beijing to study it, and now some can sing it and even perform it."},
{s:"林娜",zh:"听说有的京剧演员还要戴面具, 是吗?",es:"Dicen que algunos actores llevan máscaras, ¿es cierto?",en:"I hear some opera actors wear masks — is that true?"},
{s:"宋华",zh:"那不是面具, 那叫脸谱, 是画在演员脸上的。",es:"No son máscaras: se llama lianpu, y se pinta sobre el rostro del actor.",en:"Those aren't masks — that's lianpu, painted directly on the actor's face."},
{s:"林娜",zh:"每一次演出都需要画一次吗?",es:"¿Hay que pintarlo en cada función?",en:"Do they repaint it for every performance?"},
{s:"宋华",zh:"是啊, 京剧演员画一次脸谱需要很长时间。",es:"Sí, y pintarlo lleva mucho tiempo.",en:"Yes — painting it takes a long time."},
{s:"林娜",zh:"真不容易。你看这张海报, 下个月这儿还有芭蕾舞的演出。你想看吗? 咱们一起来看吧。",es:"Qué trabajo. Mira este cartel: el mes que viene hay ballet aquí. ¿Quieres verlo? Vengamos juntos.",en:"That's dedication. Look at this poster — there's ballet here next month. Want to see it? Let's come together."},
{s:"宋华",zh:"我还没在这个剧院看过芭蕾舞呢, 很愿意陪你看一次。",es:"Nunca vi ballet en este teatro; con gusto te acompaño.",en:"I've never seen ballet in this theater — I'd love to go with you."},
{s:"林娜",zh:"小时候我学过芭蕾舞, 学了三年。",es:"De niña estudié ballet tres años.",en:"As a kid I studied ballet for three years."},
{s:"宋华",zh:"你学过很多东西啊! 我记得你说过还学过小提琴。",es:"¡Cuántas cosas has estudiado! Recuerdo que dijiste que también tocabas violín.",en:"You've studied so much! I remember you said you also learned violin."},
{s:"林娜",zh:"对, 我来中国以后也没拉过小提琴。我想今年寒假回国的时候, 把我的小提琴带来, 学一学中国的小提琴名曲《梁祝》。",es:"Sí, aunque desde que llegué a China no lo he tocado. En las vacaciones de invierno quiero traerlo y aprender «Los amantes mariposa», la famosa pieza china.",en:"Right, though I haven't played since coming to China. Over winter break I want to bring my violin back and learn the famous Chinese piece Butterfly Lovers."},
{s:"宋华",zh:"那我一定要去听一次你的小提琴“音乐会”。",es:"Entonces iré sin falta a tu «concierto» de violín.",en:"Then I must attend your violin 'concert'."}]}]},
{l:18,t:"我们爬上长城来了",tes:"Hemos escalado la Gran Muralla",ten:"We've climbed up the Great Wall",parts:[
{ies:"La profesora Chen, Lin Na y Wang Xiaoyun están en el campus.",ien:"Teacher Chen, Lin Na and Wang Xiaoyun are on campus.",lines:[
{s:"陈老师",zh:"要放假了, 你们有什么打算?",es:"Ya llegan las vacaciones, ¿qué planes tienen?",en:"The holidays are coming — what are your plans?"},
{s:"林娜",zh:"有的去旅游, 有的想回家。",es:"Unos van a viajar; otros quieren volver a casa.",en:"Some are traveling; some want to go home."},
{s:"陈老师",zh:"小云, 你呢?",es:"Xiaoyun, ¿y tú?",en:"Xiaoyun, what about you?"},
{s:"王小云",zh:"我打算先去泰山, 再回家看我爸爸妈妈。林娜, 你去过泰山没有?",es:"Pienso ir primero al Monte Tai y luego a casa a ver a mis padres. Lin Na, ¿has estado en el Monte Tai?",en:"I plan to visit Mount Tai first, then go home to see my parents. Lin Na, have you been to Mount Tai?"},
{s:"林娜",zh:"去过一次。",es:"Una vez.",en:"Once."},
{s:"陈老师",zh:"泰山不但有优美的景色, 而且有丰富的文化, 所以说它是中国第一山。",es:"El Monte Tai no solo tiene paisajes hermosos sino también una cultura riquísima; por eso se le llama la primera montaña de China.",en:"Mount Tai has not only beautiful scenery but also rich culture — that's why it's called China's foremost mountain."},
{s:"林娜",zh:"中国第一山真是名不虚传。我还想再去一次。",es:"Su fama es bien merecida. Quiero volver otra vez.",en:"It truly lives up to its name. I'd like to go again."},
{s:"王小云",zh:"这次你打算去哪儿?",es:"¿Y esta vez adónde piensas ir?",en:"Where do you plan to go this time?"},
{s:"林娜",zh:"我想去海南。正好宋华也要去。你们知道谁还想去海南旅游吗?",es:"A Hainan; casualmente Song Hua también va. ¿Saben de alguien más que quiera ir?",en:"To Hainan — as it happens, Song Hua is going too. Know anyone else who wants to come?"},
{s:"王小云",zh:"大为说过他很喜欢海南。那儿天气好, 空气也好, 还可以欣赏南方的景色。",es:"Dawei dijo que le encanta Hainan: buen clima, buen aire y paisajes del sur para admirar.",en:"Dawei said he loves Hainan — good weather, good air, and southern scenery to admire."},
{s:"林娜",zh:"太好了, 我们问问他去不去。",es:"Perfecto, le preguntaremos si viene.",en:"Great — we'll ask if he's coming."},
{s:"陈老师",zh:"你们机票买好了吗? 要早点儿预订。",es:"¿Ya compraron los pasajes? Hay que reservar pronto.",en:"Have you bought your plane tickets? You should book early."},
{s:"林娜",zh:"还没呢。我们跟大为商量一下再买吧。力波呢?",es:"Todavía no; primero lo hablaremos con Dawei. ¿Y Libo?",en:"Not yet — we'll discuss with Dawei first. What about Libo?"},
{s:"王小云",zh:"他跟我一起去泰山。游完泰山, 我们还想去孔子的故乡看看。",es:"Él viene conmigo al Monte Tai. Después queremos visitar el pueblo natal de Confucio.",en:"He's coming with me to Mount Tai. Afterwards we want to visit Confucius's hometown."},
{s:"林娜",zh:"你们的计划也不错, 我还没去过孔子的故乡呢。",es:"Buen plan; yo aún no conozco la tierra de Confucio.",en:"Nice plan — I've never been to Confucius's hometown."},
{s:"王小云",zh:"下次我陪你去。大为还建议放假以前咱们去游一次长城。陈老师, 您能不能跟我们一起去?",es:"La próxima te acompaño. Dawei también propuso ir a la Gran Muralla antes de las vacaciones. Profesora Chen, ¿puede venir con nosotros?",en:"Next time I'll take you. Dawei also suggested a Great Wall trip before the break. Teacher Chen, can you join us?"},
{s:"陈老师",zh:"行。我很愿意跟你们一起去。",es:"Claro, con mucho gusto iré con ustedes.",en:"Sure — I'd love to go with you."}]},
{ies:"La profesora Chen está escalando la Gran Muralla con sus alumnos.",ien:"Teacher Chen is climbing the Great Wall with her students.",lines:[
{s:"王小云",zh:"陈老师、林娜, 加油! 快上来!",es:"¡Profesora Chen, Lin Na, ánimo! ¡Suban!",en:"Teacher Chen, Lin Na — come on! Hurry up!"},
{s:"陈老师",zh:"力波、大为他们呢?",es:"¿Y Libo y Dawei?",en:"Where are Libo and Dawei?"},
{s:"王小云",zh:"他们已经爬上去了。咱们也快要到山顶了。",es:"Ya subieron. Nosotras también estamos por llegar a la cima.",en:"They've already climbed up. We're almost at the top too."},
{s:"陈老师",zh:"别着急。我觉得有点儿累, 林娜也累了吧? 咱们坐下来休息一会儿。先喝点儿水, 再往上爬。",es:"Sin prisa. Estoy algo cansada, y Lin Na también, ¿no? Sentémonos a descansar: primero agua y luego seguimos.",en:"No rush. I'm a bit tired — Lin Na must be too. Let's sit and rest: drink some water first, then keep climbing."},
{s:"王小云",zh:"我饿了, 咱们得吃点儿东西。饭已经带来了, 我这儿有鸡蛋、牛奶、面包。",es:"Tengo hambre; comamos algo. Traje comida: huevos, leche y pan.",en:"I'm hungry — let's eat something. I brought food: eggs, milk, and bread."},
{s:"陈老师",zh:"这是我做的菜, 你们尝尝。",es:"Este plato lo hice yo; pruébenlo.",en:"I made this dish — try it."},
{s:"林娜",zh:"谢谢, 真好吃! 我这儿有巧克力, 小云, 你要吗?",es:"¡Gracias, qué rico! Tengo chocolate. Xiaoyun, ¿quieres?",en:"Thanks — delicious! I have chocolate. Xiaoyun, want some?"},
{s:"王小云",zh:"好啊, 我来点儿。",es:"Sí, dame un poco.",en:"Sure, I'll have a bit."},
{s:"林娜",zh:"这儿的景色多美啊! 下边都是山, 长城好像是山上的一条龙。你们看, 火车从山洞里开出来了。",es:"¡Qué paisaje tan hermoso! Abajo todo son montañas y la Muralla parece un dragón sobre ellas. Miren: el tren sale del túnel.",en:"What a gorgeous view! Mountains below, and the Wall looks like a dragon on them. Look — a train is coming out of the tunnel."},
{s:"王小云",zh:"就要开过来了, 快拍照!",es:"Ya viene, ¡foto, rápido!",en:"It's coming — quick, take a photo!"},
{s:"林娜",zh:"对, 我要多拍些照片发回家去。",es:"Sí, quiero tomar muchas fotos y enviarlas a casa.",en:"Yes — I want lots of photos to send back home."},
{s:"王小云",zh:"以前你来过这儿吗?",es:"¿Habías venido antes?",en:"Have you been here before?"},
{s:"林娜",zh:"来过, 是春天来的。那时候长城的景色跟现在很不一样。",es:"Sí, en primavera. Entonces el paisaje era muy distinto al de ahora.",en:"Yes, in spring. The scenery was very different then."},
{s:"王小云",zh:"是啊。现在是冬天, 今天还是阴天, 看样子要下雪了。",es:"Claro: ahora es invierno, hoy está nublado y parece que va a nevar.",en:"Right — it's winter now, overcast today; looks like snow."},
{s:"林娜",zh:"在长城上看下雪, 真是太美了。",es:"Ver nevar desde la Muralla debe de ser bellísimo.",en:"Watching snow fall from the Great Wall — how beautiful."},
{s:"陈老师",zh:"今天这儿的气温是零下10度。可是你们知道吗? 广州今天是零上20度。",es:"Aquí hoy estamos a 10 bajo cero; ¿y saben qué? En Guangzhou hace 20 sobre cero.",en:"It's minus 10 here today. But guess what — Guangzhou is plus 20."},
{s:"林娜",zh:"北方还是这么冷的冬天, 可是南方已经是春天了。你们看, 力波怎么走下来了?",es:"En el norte sigue el crudo invierno y en el sur ya es primavera. Miren, ¿por qué baja Libo?",en:"The north is still deep winter while the south is already spring. Look — why is Libo coming down?"},
{s:"丁力波",zh:"喂, 你们怎么还不上来? 需要帮忙吗?",es:"¡Eh! ¿Por qué no suben? ¿Necesitan ayuda?",en:"Hey, why aren't you coming up? Need help?"},
{s:"王小云",zh:"不用。你别跑过来了, 我们自己能爬上去。",es:"No hace falta; no corras hacia acá, podemos subir solas.",en:"No need — don't run over, we can climb up ourselves."},
{s:"丁力波",zh:"好吧, 我不过去了, 我在前面等你们。",es:"Bueno, no voy; las espero adelante.",en:"Fine, I won't come — I'll wait for you up ahead."},
{s:"王小云",zh:"陈老师, 您休息好了吗?",es:"Profesora, ¿ya descansó?",en:"Teacher Chen, are you rested?"},
{s:"陈老师",zh:"休息好了, 而且饭也吃了, 水也喝了。",es:"Sí, y además ya comí y bebí.",en:"Yes — and I've eaten and drunk too."},
{s:"王小云",zh:"那咱们就站起来, 继续爬吧。",es:"Entonces levantémonos y sigamos subiendo.",en:"Then let's stand up and keep climbing."},
{s:"林娜",zh:"啊! 我们终于爬上来了!",es:"¡Por fin llegamos arriba!",en:"Ah — we finally made it up!"}]}]},
{l:19,t:"汽车被我撞了",tes:"El coche fue atropellado por mí",ten:"The car got hit by me",parts:[
{ies:"Wang Xiaoyun llama a Song Hua; luego, en el hospital.",ien:"Wang Xiaoyun calls Song Hua; then at the hospital.",lines:[
{s:"王小云",zh:"宋华, 你来帮我们一下好吗?",es:"Song Hua, ¿puedes venir a ayudarnos?",en:"Song Hua, can you come help us?"},
{s:"宋华",zh:"怎么了? 你在哪儿?",es:"¿Qué pasó? ¿Dónde estás?",en:"What happened? Where are you?"},
{s:"王小云",zh:"林娜的胳膊被撞伤了, 正在第三医院检查呢。",es:"Lin Na se lastimó el brazo en un choque; le están haciendo exámenes en el Hospital N.º 3.",en:"Lin Na's arm got hurt in a collision — she's being examined at No. 3 Hospital."},
{s:"宋华",zh:"伤得重吗?",es:"¿Es grave?",en:"Is it serious?"},
{s:"王小云",zh:"还没有检查完呢。你带点儿钱来。",es:"Aún no terminan los exámenes. Trae algo de dinero.",en:"They haven't finished the check-up. Bring some money."},
{s:"宋华",zh:"好的, 你们等着, 我就来。",es:"Vale, espérenme, ya voy.",en:"OK, wait for me — I'm on my way."},
{s:"宋华",zh:"林娜, 你怎么样? 伤得重不重?",es:"Lin Na, ¿cómo estás? ¿Es grave la herida?",en:"Lin Na, how are you? Is the injury bad?"},
{s:"林娜",zh:"伤得不太重。我的右胳膊被撞伤了, 右腿也有点儿疼。",es:"No mucho: me lastimé el brazo derecho y la pierna derecha me duele un poco.",en:"Not too bad — my right arm got hurt and my right leg aches a little."},
{s:"宋华",zh:"怎么被撞伤的?",es:"¿Cómo te golpeaste?",en:"How did you get hurt?"},
{s:"林娜",zh:"别提了, 今天真倒霉。从长城回来以后, 我和小云从地铁站骑车回学校。一个司机把车停在路边, 正从车上拿东西。我跟小云说着、笑着, 聊得很高兴。我往右拐的时候没注意, 就撞到了车上。",es:"Ni lo menciones, qué día tan desafortunado. Al volver de la Muralla, Xiaoyun y yo regresamos en bici desde el metro. Un conductor había aparcado al borde y sacaba cosas del coche. Íbamos charlando y riendo tan contentas que, al girar a la derecha, no me fijé y choqué contra el coche.",en:"Don't even ask — such an unlucky day. Coming back from the Great Wall, Xiaoyun and I biked from the subway to school. A driver had parked at the roadside and was getting things from his car. We were chatting and laughing so happily that when I turned right I didn't notice and crashed into the car."},
{s:"宋华",zh:"原来你的胳膊是被自己撞伤的。你们是怎么到医院来的?",es:"O sea que el brazo te lo lastimaste tú solita. ¿Y cómo llegaron al hospital?",en:"So your arm got hurt by your own doing! How did you get to the hospital?"},
{s:"王小云",zh:"那位司机看到林娜被撞伤了, 就马上开车把我们送到了医院。",es:"El conductor, al ver a Lin Na herida, nos trajo enseguida en su coche.",en:"The driver saw Lin Na was hurt and immediately drove us to the hospital."},
{s:"宋华",zh:"那位司机真不错。",es:"Qué buen hombre.",en:"What a good guy."},
{s:"林娜",zh:"是啊, 他不但把我和小云送到医院, 而且还帮我交了医药费。因为我们带的钱不够。",es:"Sí: no solo nos trajo, sino que además pagó mis gastos médicos, porque no llevábamos suficiente dinero.",en:"Yes — he not only brought us here but also paid my medical fees, since we didn't have enough money."},
{s:"王小云",zh:"对了, 司机给了我一张名片, 在这儿呢, 说如果还有问题, 他就开车过来。",es:"Ah, me dio su tarjeta —aquí está— y dijo que si había algún problema vendría en coche.",en:"Oh — he gave me his business card, here it is, and said if there's any problem he'd drive over."},
{s:"宋华",zh:"真应该谢谢那位司机, 明天我们去把钱还给他。林娜, 刚才我还以为你被汽车撞了。",es:"Hay que agradecérselo; mañana vamos a devolverle el dinero. Lin Na, hace un momento pensaba que te había atropellado un coche.",en:"We really must thank that driver — tomorrow let's return his money. Lin Na, I thought a car had hit YOU."},
{s:"林娜",zh:"还好, 是汽车被我撞了。如果我被汽车撞了, 那就糟糕了。",es:"Menos mal que fue el coche el atropellado por mí. Si me atropella a mí, sería un desastre.",en:"Luckily the car got hit by me. If I'd been hit by the car, that would've been terrible."}]},
{ies:"Lu Yuping y Ma Dawei visitan a Lin Na en su habitación.",ien:"Lu Yuping and Ma Dawei visit Lin Na in her room.",lines:[
{s:"陆雨平",zh:"大为, 林娜宿舍的门开着, 她正躺着看报纸呢。",es:"Dawei, la puerta de Lin Na está abierta; está acostada leyendo el periódico.",en:"Dawei, Lin Na's door is open — she's lying down reading the paper."},
{s:"林娜",zh:"啊, 雨平、大为, 快进来。",es:"¡Ah, Yuping, Dawei, pasen!",en:"Ah — Yuping, Dawei, come in!"},
{s:"马大为",zh:"林娜, 你怎么样? 好点儿了吗?",es:"Lin Na, ¿cómo sigues? ¿Mejor?",en:"Lin Na, how are you? Any better?"},
{s:"林娜",zh:"好多了。你们这么忙, 还带着花儿来看我, 谢谢你们。这花儿真漂亮, 放在桌子上吧。",es:"Mucho mejor. Con lo ocupados que están, y aun así vienen con flores… gracias. Son preciosas; pónganlas en la mesa.",en:"Much better. You're so busy yet you brought flowers — thank you. They're lovely; put them on the table."},
{s:"马大为",zh:"检查的结果怎么样?",es:"¿Qué dijeron los exámenes?",en:"What were the test results?"},
{s:"林娜",zh:"医生说没什么大问题, 他让我躺着休息休息。那儿有椅子, 你们搬过来坐吧。",es:"El médico dice que no es nada grave; me mandó reposo. Allí hay sillas: acérquenlas y siéntense.",en:"The doctor says nothing serious — he told me to rest lying down. There are chairs over there; bring them over and sit."},
{s:"陆雨平",zh:"不用了, 我们站着聊一会儿。现在胳膊还疼不疼?",es:"No hace falta; charlamos de pie un rato. ¿Aún te duele el brazo?",en:"No need — we'll chat standing. Does your arm still hurt?"},
{s:"林娜",zh:"不疼了。可是胳膊这么弯着, 写字很不方便。上星期我汉字考试没考好, 现在又撞伤了胳膊, 真倒霉!",es:"Ya no. Pero con el brazo doblado así, escribir es incomodísimo. La semana pasada me fue mal en el examen de caracteres y ahora esto… ¡qué mala suerte!",en:"Not anymore. But with my arm bent like this, writing is awkward. Last week I did poorly on my character test, and now this — such bad luck!"},
{s:"马大为",zh:"我也遇到倒霉的事儿了。",es:"A mí también me pasó algo de mala suerte.",en:"Something unlucky happened to me too."},
{s:"陆雨平",zh:"你怎么了?",es:"¿Qué te pasó?",en:"What happened?"},
{s:"马大为",zh:"上星期六晚上, 我的钱包被小偷儿偷走了。",es:"El sábado por la noche un ladrón me robó la billetera.",en:"Last Saturday night a thief stole my wallet."},
{s:"陆雨平",zh:"是吗? 钱丢了, 破财免灾吧。但是里边的证件丢了就很麻烦……",es:"¿En serio? Perder dinero «ahuyenta desgracias»… pero perder los documentos sí que es un lío…",en:"Really? Losing money 'wards off disaster'… but losing the documents inside is a real hassle…"},
{s:"马大为",zh:"是啊, 我正着急呢。没想到今天上午就有了好消息。派出所给我打了一个电话, 让我去一趟。",es:"Sí, estaba angustiado. Y de pronto esta mañana, buenas noticias: la comisaría me llamó para que fuera.",en:"Yes, I was really worried. Then this morning, good news — the police station called and asked me to come by."},
{s:"林娜",zh:"你去了吗?",es:"¿Fuiste?",en:"Did you go?"},
{s:"马大为",zh:"去了。他们告诉我, 那个小偷儿昨天在公共汽车上偷东西的时候被人抓住了。所以我的钱包也就找到了, 证件都在。",es:"Sí. Me dijeron que ayer atraparon al ladrón robando en un autobús, así que apareció mi billetera con todos los documentos.",en:"I did. They told me the thief was caught stealing on a bus yesterday, so my wallet turned up — documents and all."},
{s:"林娜",zh:"真是个好消息。你的运气真好!",es:"¡Qué buena noticia! ¡Tienes mucha suerte!",en:"What great news — you're so lucky!"},
{s:"马大为",zh:"你的运气也不坏, 听说你们认识了一位好心的司机朋友。",es:"La tuya tampoco es mala: supe que conocieron a un conductor de buen corazón.",en:"Your luck isn't bad either — I hear you made friends with a kind-hearted driver."},
{s:"陆雨平",zh:"因祸得福。你好好儿休息吧, 我们该走了。祝你早日康复!",es:"No hay mal que por bien no venga. Descansa bien; nos vamos. ¡Que te recuperes pronto!",en:"A blessing in disguise. Rest well — we should go. Get well soon!"},
{s:"林娜",zh:"谢谢你们!",es:"¡Gracias a los dos!",en:"Thank you both!"}]}]},
{l:20,t:"请把电脑拿出来",tes:"Por favor, saca tu computadora",ten:"Please take out your computer",parts:[
{ies:"Ma Dawei está registrándose en el aeropuerto.",ien:"Ma Dawei is checking in at the airport.",lines:[
{s:"工作人员",zh:"您好! 请把您的护照给我。",es:"¡Hola! Su pasaporte, por favor.",en:"Hello! Your passport, please."},
{s:"马大为",zh:"请等一下, 我把护照放在背包里了。在这儿, 给您! 我想要一个靠窗户的座位。",es:"Un momento, lo guardé en la mochila. ¡Aquí tiene! Quisiera un asiento junto a la ventanilla.",en:"One moment — I put it in my backpack. Here you go! I'd like a window seat."},
{s:"工作人员",zh:"靠窗户的座位都被选完了, 我给您选一个靠过道的吧。",es:"Los de ventanilla ya están todos tomados; le asigno uno de pasillo.",en:"The window seats are all taken — I'll give you an aisle seat."},
{s:"马大为",zh:"好吧。我有个行李箱要托运。",es:"Está bien. Tengo una maleta para facturar.",en:"All right. I have a suitcase to check in."},
{s:"工作人员",zh:"好, 请您把行李箱搬上来。这个行李超重了, 超了三公斤。",es:"Bien, súbala aquí. Su equipaje excede el peso: tres kilos de más.",en:"OK, lift it up here. Your luggage is overweight — by three kilos."},
{s:"马大为",zh:"那我把里面的书拿出来, 放在背包里。",es:"Entonces saco los libros y los meto en la mochila.",en:"Then I'll take the books out and put them in my backpack."},
{s:"工作人员",zh:"好的。现在可以了。请把您的护照和登机牌收好。",es:"Perfecto, ahora sí. Guarde bien su pasaporte y su tarjeta de embarque.",en:"Good — that works now. Please keep your passport and boarding pass safe."},
{s:"工作人员",zh:"请把手机、电脑拿出来, 把外衣和鞋子脱下来。",es:"Saque el móvil y la computadora, y quítese el abrigo y los zapatos.",en:"Take out your phone and computer, and remove your coat and shoes."},
{s:"马大为",zh:"要把鞋子也放进筐里去吗?",es:"¿Los zapatos también van en la bandeja?",en:"Do the shoes go in the bin too?"},
{s:"工作人员",zh:"对, 都放在筐里。",es:"Sí, todo en la bandeja.",en:"Yes, everything in the bin."},
{s:"工作人员",zh:"先生, 这个包是您的吧?",es:"Señor, esta mochila es suya, ¿verdad?",en:"Sir, this bag is yours, right?"},
{s:"马大为",zh:"是我的。",es:"Sí, mía.",en:"It's mine."},
{s:"工作人员",zh:"对不起, 要打开检查, 请到这边来。这个瓶子里是什么? 您不能把它带上飞机去。",es:"Disculpe, hay que abrirla para revisar; venga por aquí. ¿Qué hay en esta botella? No puede subirla al avión.",en:"Sorry, we need to open and inspect it — this way please. What's in this bottle? You can't take it on the plane."},
{s:"马大为",zh:"哎呀, 是水。我刚才没喝完, 就把瓶子放进包里去了。不好意思啊。",es:"Ay, es agua: no la terminé y metí la botella en la mochila. ¡Qué pena!",en:"Oops — it's water. I didn't finish it and stuck the bottle in my bag. Sorry about that!"}]},
{ies:"En la puerta de embarque, Ma Dawei consulta a la pasajera Bai Xiaoyan sentada a su lado.",ien:"At the boarding gate, Ma Dawei asks fellow passenger Bai Xiaoyan next to him.",lines:[
{s:"广播",zh:"前往洛杉矶的旅客请注意: 您乘坐的CA983次航班现在开始登机。请带好您的随身物品, 出示登机牌, 由32号登机口登机。祝您旅途愉快。谢谢!",es:"Pasajeros con destino a Los Ángeles: el vuelo CA983 inicia ahora el embarque. Lleven sus pertenencias, muestren su tarjeta de embarque y aborden por la puerta 32. Feliz viaje. ¡Gracias!",en:"Passengers to Los Angeles: flight CA983 is now boarding. Please take your belongings, show your boarding pass, and board at gate 32. Have a pleasant journey. Thank you!"},
{s:"马大为",zh:"请问, 广播里说什么了?",es:"Disculpe, ¿qué dijo el altavoz?",en:"Excuse me, what did the announcement say?"},
{s:"白小燕",zh:"去美国的航班开始登机了。",es:"Que el vuelo a Estados Unidos ya embarca.",en:"The flight to the US is boarding."},
{s:"马大为",zh:"谢谢。您也坐这班飞机?",es:"Gracias. ¿Usted también va en este vuelo?",en:"Thanks. Are you on this flight too?"},
{s:"白小燕",zh:"是啊。",es:"Así es.",en:"I am."},
{s:"马大为",zh:"咱们该认识一下了: 我叫马大为, 您怎么称呼?",es:"Deberíamos presentarnos: me llamo Ma Dawei, ¿y usted?",en:"We should introduce ourselves — I'm Ma Dawei. How should I address you?"},
{s:"白小燕",zh:"我姓白, 叫白小燕。我在旅游公司工作, 这是我的名片。",es:"Mi apellido es Bai: Bai Xiaoyan. Trabajo en una agencia de viajes; aquí tiene mi tarjeta.",en:"My surname is Bai — Bai Xiaoyan. I work at a travel company; here's my card."},
{s:"马大为",zh:"白——小——燕, 这个名字真美。啊, 是白经理!",es:"Bai… Xiao… yan, ¡qué nombre tan bonito! ¡Ah, es la gerente Bai!",en:"Bai — Xiao — yan… what a beautiful name. Ah, Manager Bai!"},
{s:"白小燕",zh:"不客气, 大家都叫我小燕子。您是来北京旅游的吧?",es:"Sin formalidades: todos me dicen Golondrinita. ¿Vino a Beijing de turismo?",en:"No need for formality — everyone calls me Little Swallow. You came to Beijing as a tourist?"},
{s:"马大为",zh:"我不是来旅游的, 我是来学汉语的, 已经学了一年了。现在要回国一趟, 看看父母。",es:"No: vine a estudiar chino y ya llevo un año. Ahora vuelvo a mi país una temporada a ver a mis padres.",en:"Not as a tourist — I came to study Chinese, a year now. I'm heading home for a bit to see my parents."},
{s:"白小燕",zh:"您还要回北京来吗?",es:"¿Volverá a Beijing?",en:"Will you come back to Beijing?"},
{s:"马大为",zh:"当然, 我要在北京再学一年汉语。以后如果我想旅游, 就找您了。",es:"Claro: estudiaré un año más de chino. Y si luego quiero viajar, la buscaré a usted.",en:"Of course — one more year of Chinese. And if I want to travel later, I'll look you up."},
{s:"白小燕",zh:"没问题, 欢迎找我们公司。学完汉语, 您打算在中国工作吗?",es:"Encantada; nuestra agencia lo atenderá. Al terminar el chino, ¿piensa trabajar en China?",en:"No problem — our company welcomes you. After your studies, do you plan to work in China?"},
{s:"马大为",zh:"怎么说呢? 现在还不好决定。我的专业是国际贸易。中国经济发展得很快, 我们会中文的找工作的机会也越来越多。我正在联系这儿的贸易公司, 希望能找到合适的工作。我想在北京再待两年, 提高我的汉语水平, 还能了解更多的中国文化。",es:"¿Cómo decirlo? Aún es difícil decidir. Mi especialidad es el comercio internacional; con lo rápido que crece la economía china, quienes hablamos chino tenemos cada vez más oportunidades. Estoy contactando empresas de comercio de aquí y espero encontrar un buen trabajo. Quisiera quedarme dos años más en Beijing para mejorar mi chino y conocer más la cultura china.",en:"How to put it? Hard to decide yet. My major is international trade; with China's economy growing so fast, those of us who speak Chinese have more and more opportunities. I'm contacting trade companies here hoping to find a suitable job. I'd like two more years in Beijing to improve my Chinese and learn more about Chinese culture."},
{s:"白小燕",zh:"您对中国文化很感兴趣。",es:"Le interesa mucho la cultura china.",en:"You're really interested in Chinese culture."},
{s:"马大为",zh:"是特别感兴趣。我喜欢看京剧、打太极拳、吃中国菜, 最喜欢在中国旅游。您这次是去美国工作的吗?",es:"Muchísimo: me gusta la ópera de Beijing, el taichí, la comida china y, sobre todo, viajar por China. ¿Usted va a Estados Unidos por trabajo?",en:"Especially interested — I love Beijing opera, tai chi, Chinese food, and most of all traveling in China. Are you going to the US for work?"},
{s:"白小燕",zh:"我去美国学习旅游业务, 在那儿待三个月。",es:"Voy a estudiar el negocio turístico; estaré tres meses.",en:"I'm going to study the tourism business — three months there."},
{s:"马大为",zh:"这很好啊。您以前去过美国吗?",es:"¡Qué bien! ¿Había estado antes en Estados Unidos?",en:"That's great. Have you been to the US before?"},
{s:"白小燕",zh:"没有, 这是第一次。不知道我能不能习惯那儿的生活。",es:"No, es la primera vez. No sé si me acostumbraré a la vida de allá.",en:"No, it's my first time. I wonder if I'll get used to life there."},
{s:"马大为",zh:"应该没问题。您有微信吗? 如果有什么问题, 可以跟我联系, 说不定我能帮点儿忙。",es:"Seguro que sí. ¿Tiene WeChat? Si surge algún problema, contácteme; quizá pueda ayudarla.",en:"You'll be fine. Do you have WeChat? If anything comes up, contact me — maybe I can help."},
{s:"白小燕",zh:"太好了! 谢谢您。",es:"¡Estupendo! Gracias.",en:"Wonderful! Thank you."},
{s:"马大为",zh:"客气什么? “在家靠父母, 出门靠朋友”, 对吧?",es:"¿Por qué tanta cortesía? «En casa cuentas con tus padres; fuera, con tus amigos», ¿no?",en:"No need to thank me. 'At home you rely on your parents; away from home, on friends' — right?"},
{s:"白小燕",zh:"您真是“中国通”啊!",es:"¡Es usted todo un experto en China!",en:"You really are a 'China hand'!"}]}]}
];
